* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; background: #f0f2f5; color: #222; }
header { padding: 16px 24px; background: #fff; border-bottom: 1px solid #ddd; }
h1 { margin: 0 0 12px; font-size: 1.4rem; }
form { display: flex; gap: 8px; flex-wrap: wrap; }
input, select, button { font: inherit; padding: 8px 10px; }
input { flex: 1; min-width: 200px; }
button { background: #2563eb; color: #fff; border: 0; border-radius: 4px; cursor: pointer; }
#error { color: #b91c1c; margin: 8px 0 0; min-height: 1em; }
#board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; padding: 24px; align-items: start; }
.column { background: #e4e7ec; border-radius: 8px; padding: 12px; min-height: 120px; }
.column h2 { margin: 0 0 10px; font-size: 1rem; }
.card { background: #fff; border-radius: 6px; padding: 10px; margin-bottom: 8px; box-shadow: 0 1px 2px rgba(0,0,0,.12); overflow-wrap: anywhere; }
@media (max-width: 700px) { #board { grid-template-columns: 1fr; } }
.card { display: flex; justify-content: space-between; align-items: center; gap: 8px; cursor: grab; }
.card .delete { border: none; background: none; cursor: pointer; font-size: 1.1em; color: #888; }
.card .delete:hover { color: #c00; }
.column.over { outline: 2px dashed #888; }

